using System.Runtime.CompilerServices;
using System.Runtime.InteropServices;
using System.Runtime.Intrinsics;

namespace ProdOp;

public static class MathOps
{
    /// <summary>Computes the product of all elements.</summary>
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    public static float Product(ReadOnlySpan<float> values)
    {
        if (values.IsEmpty) return 0f;

        int i = 0;

        // SIMD path: 4 independent accumulators hide multiply latency (~4 cycles).
        if (Vector256.IsHardwareAccelerated && values.Length >= Vector256<float>.Count * 4)
        {
            ref float start = ref MemoryMarshal.GetReference(values);

            var acc0 = Vector256.Create(1f);
            var acc1 = Vector256.Create(1f);
            var acc2 = Vector256.Create(1f);
            var acc3 = Vector256.Create(1f);

            int stride = Vector256<float>.Count * 4; // 32 floats per iteration
            int limit = values.Length - stride + 1;

            for (; i < limit; i += stride)
            {
                acc0 *= Vector256.LoadUnsafe(ref start, (nuint)i);
                acc1 *= Vector256.LoadUnsafe(ref start, (nuint)(i + Vector256<float>.Count));
                acc2 *= Vector256.LoadUnsafe(ref start, (nuint)(i + Vector256<float>.Count * 2));
                acc3 *= Vector256.LoadUnsafe(ref start, (nuint)(i + Vector256<float>.Count * 3));
            }

            // Collapse accumulators
            acc0 = (acc0 * acc1) * (acc2 * acc3);
            float product = acc0[0] * acc0[1] * acc0[2] * acc0[3]
                          * acc0[4] * acc0[5] * acc0[6] * acc0[7];

            // Scalar remainder
            for (; i < values.Length; i++)
                product *= values[i];

            return product;
        }

        if (Vector128.IsHardwareAccelerated && values.Length >= Vector128<float>.Count * 4)
        {
            ref float start = ref MemoryMarshal.GetReference(values);

            var acc0 = Vector128.Create(1f);
            var acc1 = Vector128.Create(1f);
            var acc2 = Vector128.Create(1f);
            var acc3 = Vector128.Create(1f);

            int stride = Vector128<float>.Count * 4; // 16 floats per iteration
            int limit = values.Length - stride + 1;

            for (; i < limit; i += stride)
            {
                acc0 *= Vector128.LoadUnsafe(ref start, (nuint)i);
                acc1 *= Vector128.LoadUnsafe(ref start, (nuint)(i + Vector128<float>.Count));
                acc2 *= Vector128.LoadUnsafe(ref start, (nuint)(i + Vector128<float>.Count * 2));
                acc3 *= Vector128.LoadUnsafe(ref start, (nuint)(i + Vector128<float>.Count * 3));
            }

            acc0 = (acc0 * acc1) * (acc2 * acc3);
            float product = acc0[0] * acc0[1] * acc0[2] * acc0[3];

            for (; i < values.Length; i++)
                product *= values[i];

            return product;
        }

        // Scalar fallback with 4x unrolling
        {
            float p0 = 1f, p1 = 1f, p2 = 1f, p3 = 1f;
            int limit = values.Length - 3;
            for (; i < limit; i += 4)
            {
                p0 *= values[i];
                p1 *= values[i + 1];
                p2 *= values[i + 2];
                p3 *= values[i + 3];
            }
            float product = (p0 * p1) * (p2 * p3);
            for (; i < values.Length; i++)
                product *= values[i];
            return product;
        }
    }
}

